)

type SettingsProvider interface {
	CurrentSettings() settings.Config
}

type Notifier interface {
	OnSystemMessage(event ui.SystemEvent) error
}

type ContextSink interface {
	SubmitSupplement(input string) bool
}

type Store interface {
	session.Store
	TranscriptPath(sessionID string) string
}

type Config struct {
	Model    loop.ModelStreamer
	Store    Store
	Root     string
	Settings SettingsProvider
	Notifier Notifier
	Context  ContextSink
	Launcher Launcher

	Depth        int
	MaxDepth     int
	ParentTaskID string
}

type Manager struct {
	model        loop.ModelStreamer
	store        Store
	root         string
	settings     SettingsProvider
	notifier     Notifier
	contextSink  ContextSink
	launcher     Launcher
	registry     taskRegistry
	depth        int
	maxDepth     int
	parentTaskID string

	startMu sync.Mutex
	mu      sync.RWMutex
	tasks   map[string]TaskSnapshot
	running map[string]Process
}

type Request struct {
	ParentSessionID string
	Prompt          string
	Description     string
	ContextMode     settings.ContextMode
	RunMode         settings.RunMode
}

type Result struct {
	AgentID        string               `json:"agent_id"`
	AgentName      string               `json:"agent_name,omitempty"`
	AgentColor     string               `json:"agent_color,omitempty"`
	SessionID      string               `json:"session_id"`
	ContextMode    settings.ContextMode `json:"context_mode"`
	RunMode        settings.RunMode     `json:"run_mode"`
	TranscriptPath string               `json:"transcript_path"`
	OutputPath     string               `json:"output_path,omitempty"`
	ExitCode       *int                 `json:"exit_code,omitempty"`
	Depth          int                  `json:"depth"`
	ParentTaskID   string               `json:"parent_task_id,omitempty"`
	Content        string               `json:"content,omitempty"`
}

type TaskStatus string

const (
	TaskRunning   TaskStatus = "running"
	TaskCompleted TaskStatus = "completed"
	TaskFailed    TaskStatus = "failed"
	TaskStopped   TaskStatus = "stopped"
)

type TaskSnapshot struct {
	ID              string               `json:"id"`
	Name            string               `json:"name,omitempty"`
	Color           string               `json:"color,omitempty"`
	SessionID       string               `json:"session_id"`
